package club.abelix.games.fakevival.managers;

import club.abelix.games.fakevival.Game;
import club.abelix.games.fakevival.data.DataManager;
import club.abelix.games.fakevival.menus.MenuHolder;
import club.abelix.games.fakevival.util.CC;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.EntityTargetLivingEntityEvent;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryDragEvent;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.event.player.PlayerChangedWorldEvent;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;

import java.sql.*;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

public final class DungeonSpectateService implements Listener {
    private static final int[] SLOTS={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34};
    private final Game game;private final DataManager data;private final NamespacedKey actionKey;
    private final Map<UUID,SpectatorState> states=new ConcurrentHashMap<>();
    public DungeonSpectateService(Game game,DataManager data){this.game=game;this.data=data;this.actionKey=new NamespacedKey(game,"dungeon_spectate_action");}

    public void openRuns(Player staff,int page){if(!allowed(staff))return;asyncRuns().whenComplete((runs,error)->sync(()->{if(error!=null){staff.sendMessage(CC.color("&cCould not load dungeon runs."));return;}Inventory inv=Bukkit.createInventory(new MenuHolder("dungeon-spectate:"+page),54,CC.color("&8Dungeon Spectate"));int pages=Math.max(1,(runs.size()+20)/21);int safe=Math.clamp(page,0,pages-1),start=safe*21;for(int i=0;i<21&&start+i<runs.size();i++){RunRow run=runs.get(start+i);inv.setItem(SLOTS[i],item(Material.ENDER_EYE,"&d"+pretty(run.dungeonId),List.of("&7Run ID: &e"+run.runId,"&7Server: &b"+run.serverId,"&7State: &a"+run.state,"&7Players: &e"+run.players,"&7Boss: &c"+run.bossName,"&7Time: &e"+duration(System.currentTimeMillis()-run.createdAt),"","&eClick to view players!"),"run:"+run.runId));}if(safe>0)inv.setItem(45,item(Material.ARROW,"&aPrevious Page",List.of("&eClick to browse!"),"runs:"+(safe-1)));inv.setItem(49,item(Material.BARRIER,"&cClose",List.of(),"close"));if(safe+1<pages)inv.setItem(53,item(Material.ARROW,"&aNext Page",List.of("&eClick to browse!"),"runs:"+(safe+1)));fill(inv);staff.openInventory(inv);}));}
    public void sendRunList(org.bukkit.command.CommandSender sender){asyncRuns().whenComplete((runs,error)->sync(()->{if(error!=null){sender.sendMessage(CC.color("&cCould not load dungeon runs."));return;}if(runs.isEmpty()){sender.sendMessage(CC.color("&7There are no active dungeon runs."));return;}for(RunRow run:runs)sender.sendMessage(CC.color("&7Run: &e"+run.runId+" &7Dungeon: &d"+run.dungeonId+" &7State: &a"+run.state+" &7Players: &e"+run.players+" &7Server: &b"+run.serverId));}));}
    public void openPlayers(Player staff,String runId){if(!allowed(staff))return;asyncPlayers(runId).whenComplete((players,error)->sync(()->{if(error!=null||players.isEmpty()){staff.sendMessage(CC.color("&cThat dungeon run is no longer active."));return;}Inventory inv=Bukkit.createInventory(new MenuHolder("dungeon-spectate-players:"+runId),54,CC.color("&8Dungeon Players"));for(int i=0;i<Math.min(21,players.size());i++){PlayerRow row=players.get(i);Player online=Bukkit.getPlayer(row.uuid);inv.setItem(SLOTS[i],item(Material.PLAYER_HEAD,"&b"+(online==null?row.uuid.toString().substring(0,8):online.getName()),List.of("&7Dungeon: &d"+pretty(row.dungeonId),"&7Server: &b"+row.serverId,"&7State: &a"+row.state,"&7Health: &c"+(int)Math.ceil(row.health)+"&7/&c"+(int)Math.ceil(row.maxHealth),"&7Location: &e"+(int)row.x+", "+(int)row.y+", "+(int)row.z,"&7World: &e"+row.world,"","&eClick to spectate!"),"player:"+row.uuid+":"+row.runId+":"+row.serverId));}inv.setItem(49,item(Material.ARROW,"&cBack",List.of(),"runs:0"));fill(inv);staff.openInventory(inv);}));}

    @EventHandler public void click(InventoryClickEvent event){if(!(event.getInventory().getHolder() instanceof MenuHolder(String type))||!type.startsWith("dungeon-spectate"))return;event.setCancelled(true);if(!(event.getWhoClicked() instanceof Player staff)||event.getClickedInventory()!=event.getView().getTopInventory())return;String action=action(event.getCurrentItem());if(action==null)return;if(action.equals("close")){staff.closeInventory();return;}if(action.startsWith("runs:")){openRuns(staff,number(action.substring(5)));return;}if(action.startsWith("run:")){openPlayers(staff,action.substring(4));return;}if(action.startsWith("player:")){String[] parts=action.split(":",4);if(parts.length==4)spectate(staff,UUID.fromString(parts[1]),parts[2],parts[3]);}}
    @EventHandler public void drag(InventoryDragEvent event){if(event.getInventory().getHolder() instanceof MenuHolder(String type)&&type.startsWith("dungeon-spectate"))event.setCancelled(true);}
    @EventHandler public void target(EntityTargetLivingEntityEvent event){if(event.getTarget() instanceof Player player&&isSpectating(player))event.setCancelled(true);}
    @EventHandler public void damage(EntityDamageEvent event){if(event.getEntity() instanceof Player player&&isSpectating(player))event.setCancelled(true);}
    @EventHandler public void quit(PlayerQuitEvent event){if(!isSpectating(event.getPlayer()))game.getDungeonManager().handleParticipantQuit(event.getPlayer());}
    @EventHandler public void worldChange(PlayerChangedWorldEvent event){if(!isSpectating(event.getPlayer())&&game.getDungeonManager().isActiveDungeonInstanceWorld(event.getFrom())&&!game.getDungeonManager().isActiveDungeonInstanceWorld(event.getPlayer().getWorld())){game.getDungeonManager().handleParticipantQuit(event.getPlayer());event.getPlayer().sendMessage(CC.color("&eYour dungeon will stay open for &c5 minutes&e. Rejoin before it closes."));}}
    @EventHandler public void join(PlayerJoinEvent event){if(!data.isMySqlEnabled())return;UUID staff=event.getPlayer().getUniqueId();CompletableFuture.runAsync(()->consumePending(staff));}

    public void spectate(Player staff,UUID targetUuid,String runId,String serverId){if(!allowed(staff))return;Player target=Bukkit.getPlayer(targetUuid);if(serverId.equalsIgnoreCase(game.getNetworkService().getCurrentServerId())&&target!=null){activate(staff,target,runId);return;}if(!data.isMySqlEnabled()){staff.sendMessage(CC.color("&cThat dungeon run is no longer active."));return;}CompletableFuture.runAsync(()->{long now=System.currentTimeMillis();try(Connection c=data.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO smp_pending_dungeon_spectates(spectate_id,staff_uuid,target_uuid,dungeon_run_id,target_server_id,created_at,expires_at) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE target_uuid=VALUES(target_uuid),dungeon_run_id=VALUES(dungeon_run_id),target_server_id=VALUES(target_server_id),created_at=VALUES(created_at),expires_at=VALUES(expires_at)")){s.setString(1,"spectate_"+staff.getUniqueId());s.setString(2,staff.getUniqueId().toString());s.setString(3,targetUuid.toString());s.setString(4,runId);s.setString(5,serverId);s.setLong(6,now);s.setLong(7,now+30_000);s.executeUpdate();sync(()->game.getNetworkService().transferPlayer(staff,serverId));}catch(SQLException e){sync(()->staff.sendMessage(CC.color("&cThat dungeon run is no longer active.")));}});}
    public void leave(Player staff){SpectatorState state=states.remove(staff.getUniqueId());game.getDungeonManager().removeSpectator(staff);if(state!=null){game.getVanishManager().setVanished(staff,state.wasVanished);staff.setGameMode(state.gameMode);staff.setAllowFlight(state.allowFlight);staff.setFlying(state.flying&&state.allowFlight);if(state.returnLocation!=null&&state.returnLocation.getWorld()!=null)staff.teleport(state.returnLocation);}staff.sendMessage(CC.color("&aYou left dungeon spectate mode."));}
    public boolean isSpectating(Player player){return states.containsKey(player.getUniqueId())||game.getDungeonManager().isSpectating(player);}
    public void shutdown(){for(UUID uuid:new ArrayList<>(states.keySet())){Player staff=Bukkit.getPlayer(uuid);if(staff!=null)leave(staff);}states.clear();}

    private void activate(Player staff,Player target,String runId){if(!target.isOnline()){staff.sendMessage(CC.color("&cThat dungeon run is no longer active."));return;}states.putIfAbsent(staff.getUniqueId(),new SpectatorState(staff.getLocation().clone(),staff.getGameMode(),staff.getAllowFlight(),staff.isFlying(),game.getVanishManager().isVanished(staff)));game.getVanishManager().setVanished(staff,true);staff.setAllowFlight(true);staff.setFlying(true);game.getDungeonManager().addSpectator(runId,staff);staff.teleport(target.getLocation().clone().add(0,1.5,0));staff.sendMessage(CC.color("&aNow spectating &e"+target.getName()+"&a's dungeon run."));}
    private boolean allowed(Player staff){if(staff.hasPermission("fakevival.dungeon.spectate"))return true;staff.sendMessage(CC.color("&cYou do not have permission to spectate dungeons."));return false;}
    private void consumePending(UUID staff){long now=System.currentTimeMillis();try(Connection c=data.getConnection()){c.setAutoCommit(false);UUID target=null;String run=null;try(PreparedStatement s=c.prepareStatement("SELECT target_uuid,dungeon_run_id FROM smp_pending_dungeon_spectates WHERE staff_uuid=? AND target_server_id=? AND expires_at>=? FOR UPDATE")){s.setString(1,staff.toString());s.setString(2,game.getNetworkService().getCurrentServerId());s.setLong(3,now);try(ResultSet r=s.executeQuery()){if(r.next()){target=UUID.fromString(r.getString(1));run=r.getString(2);}}}if(target!=null)try(PreparedStatement d=c.prepareStatement("DELETE FROM smp_pending_dungeon_spectates WHERE staff_uuid=?")){d.setString(1,staff.toString());d.executeUpdate();}c.commit();if(target!=null){UUID finalTarget=target;String finalRun=run;syncLater(()->{Player viewer=Bukkit.getPlayer(staff),watched=Bukkit.getPlayer(finalTarget);if(viewer!=null&&watched!=null)activate(viewer,watched,finalRun);else if(viewer!=null)viewer.sendMessage(CC.color("&cThat dungeon run is no longer active."));},2L);}}catch(Exception e){game.getLogger().warning("[SMP] Pending dungeon spectate consume failed: "+e.getMessage());}}

    private CompletableFuture<List<RunRow>> asyncRuns(){return CompletableFuture.supplyAsync(()->{List<RunRow> rows=new ArrayList<>();try(Connection c=data.getConnection();PreparedStatement s=c.prepareStatement("SELECT r.*,COUNT(CASE WHEN p.online=TRUE THEN 1 END) players FROM smp_dungeon_runs r LEFT JOIN smp_dungeon_run_players p ON p.run_id=r.run_id WHERE r.state IN ('ACTIVE','EMPTY_WAITING_FOR_REJOIN') AND (r.expires_at=0 OR r.expires_at>?) GROUP BY r.run_id ORDER BY r.created_at DESC")){s.setLong(1,System.currentTimeMillis());try(ResultSet r=s.executeQuery()){while(r.next())rows.add(new RunRow(r.getString("run_id"),r.getString("dungeon_id"),r.getString("server_id"),r.getString("state"),r.getInt("players"),r.getString("boss_name"),r.getLong("created_at")));}}catch(SQLException e){throw new java.util.concurrent.CompletionException(e);}return rows;});}
    private CompletableFuture<List<PlayerRow>> asyncPlayers(String runId){return CompletableFuture.supplyAsync(()->{List<PlayerRow> rows=new ArrayList<>();try(Connection c=data.getConnection();PreparedStatement s=c.prepareStatement("SELECT p.*,r.dungeon_id,r.state FROM smp_dungeon_run_players p JOIN smp_dungeon_runs r ON r.run_id=p.run_id WHERE p.run_id=? AND r.state IN ('ACTIVE','EMPTY_WAITING_FOR_REJOIN') ORDER BY p.online DESC,p.updated_at DESC")){s.setString(1,runId);try(ResultSet r=s.executeQuery()){while(r.next())rows.add(new PlayerRow(UUID.fromString(r.getString("uuid")),runId,r.getString("server_id"),r.getString("world"),r.getDouble("x"),r.getDouble("y"),r.getDouble("z"),r.getString("dungeon_id"),r.getString("state"),r.getDouble("current_health"),r.getDouble("max_health")));}}catch(SQLException e){throw new java.util.concurrent.CompletionException(e);}return rows;});}
    private ItemStack item(Material material,String name,List<String> lore,String action){ItemStack item=new ItemStack(material);ItemMeta meta=item.getItemMeta();meta.setDisplayName(CC.color(name));meta.setLore(lore.stream().map(CC::color).toList());if(action!=null)meta.getPersistentDataContainer().set(actionKey,PersistentDataType.STRING,action);item.setItemMeta(meta);return item;}
    private String action(ItemStack item){return item==null||!item.hasItemMeta()?null:item.getItemMeta().getPersistentDataContainer().get(actionKey,PersistentDataType.STRING);}
    private void fill(Inventory inv){ItemStack pane=item(Material.BLACK_STAINED_GLASS_PANE," ",List.of(),null);for(int i=0;i<inv.getSize();i++)if(inv.getItem(i)==null)inv.setItem(i,pane);}
    private void sync(Runnable task){Bukkit.getScheduler().runTask(game,task);}private void syncLater(Runnable task,long ticks){Bukkit.getScheduler().runTaskLater(game,task,ticks);}
    private int number(String value){try{return Integer.parseInt(value);}catch(Exception ignored){return 0;}}private String pretty(String value){String[] parts=value.replace('-','_').split("_");StringBuilder out=new StringBuilder();for(String p:parts){if(p.isBlank())continue;if(!out.isEmpty())out.append(' ');out.append(Character.toUpperCase(p.charAt(0))).append(p.substring(1));}return out.toString();}private String duration(long ms){long seconds=Math.max(0,ms/1000),minutes=seconds/60;return minutes+"m "+seconds%60+"s";}
    private record RunRow(String runId,String dungeonId,String serverId,String state,int players,String bossName,long createdAt){}private record PlayerRow(UUID uuid,String runId,String serverId,String world,double x,double y,double z,String dungeonId,String state,double health,double maxHealth){}private record SpectatorState(Location returnLocation,GameMode gameMode,boolean allowFlight,boolean flying,boolean wasVanished){}
}
